INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (136, 'source_value_extractions', 'claim_text', '105', '57930ff6487a3ed3f1b2b20762fc3f283c138e2a7b3d27767f4331ee111b7ad5', 'EN', 'an inclined plane with a slope of 5% or less will be preferred', 'rejected', 'model', 'claude-opus-5-5', 'judgment', NULL, 'model', 'claude-opus-5-5 (independent reviewing instance)', '2026-11-20 06:53', 'original cell is truncated: the cell starts mid-sentence after a semicolon and drops what the ramp is preferred to; the full passage reads ''L''aménagement de ressauts successifs est déconseillé car la répétitivité de l''obstacle que constitue le ressaut est très pénible pour les personnes en fauteuil roulant ; on préférera un plan incliné dont la pente est inférieure ou égale à 5 %'' (''A series of successive small steps is discouraged ...; an inclined plane of 5% or less is preferred'').', NULL, '2026-11-20 06:53', 'session_2026-11-20-core-work', '2026-11-20 06:53', 'session_2026-11-20-core-work');
