INSERT INTO "translations" ("translation_id", "source_table", "source_column", "source_row_key", "source_sha256", "target_language", "translated_text", "status", "translator_kind", "translator_name", "requested_at_stage", "due_stage", "reviewed_by_kind", "reviewed_by_name", "reviewed_at", "review_reason", "superseded_by_translation_id", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (142, 'source_value_extractions', 'claim_text', '111', '4a2c92b80b5e0ac54a4b39d171b0507d2912df7cb9fd61b72eccac65b8f1735e', 'EN', 'In the case of buildings undergoing alteration or conservation works, if space limitations prevent the use of ramps with a slope not exceeding 8%, the ramps may have steeper slopes if they satisfy one of the following situations, or values interpolated from those indicated: 1) Have a slope not exceeding 10%, overcome a level difference not exceeding 0.2 m and have a horizontal projection not exceeding 2 m; 2) Have a slope not exceeding 12%, overcome a level difference not exceeding 0.1 m and have a horizontal projection not exceeding 0.83 m.', 'reviewed', 'model', 'claude-opus-5-5', 'judgment', NULL, 'model', 'claude-opus-5-5 (independent reviewing instance)', '2026-11-20 06:54', 'Independent review against the original by a different Opus-class instance (OD-30): numbers, units, inequalities, conditions and technical terms checked. A blind second translation by claude-sonnet-5-5 was an aid, not the review. A model, not a person.', NULL, '2026-11-20 06:54', 'session_2026-11-20-core-work', '2026-11-20 06:54', 'session_2026-11-20-core-work');
