INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-372', 'SW', 'P2', 'OPEN', 'run-pipeline', NULL, 'These claim_text cells are cut off in the stored extraction, so no honest English rendering exists and each was rejected at review: extraction ids 30, 102, 105, 112, 115, 141, 202, 207, 208, 209, 215. The full passage of each is quoted in the review_reason of its rejected translation (select source_row_key, review_reason from translations where status=''rejected''). Repair each claim_text from the logged payload through the extraction writer, then request its translation again; until then they are listed owed by db.py translations --due-at judgment.', '2026-11-20 06:55', 'session_2026-11-20-core-work', '2026-11-20 06:55', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-373', 'SW', 'P2', 'OPEN', 'run-pipeline', NULL, 'Non-English text outside source titles and figure claim_text is not owed and not translated, so an English reader cannot read it: the clause labels in source_value_extractions.source_section and the loc_* columns, extraction_relations.quote, observed_terms.context_quote, Korean inside claimed_unit, and corporate author names that carry English inside one cell. db._translations_owed lists pub_title and claim_text only. Decide which of these the base must hold in English, then widen _translations_owed by data, not by a list of columns.', '2026-11-20 06:55', 'session_2026-11-20-core-work', '2026-11-20 06:55', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-374', 'SW', 'P3', 'OPEN', 'run-pipeline', NULL, 'retrieval_log._failure_reason accepts any HTTP 2xx, so a page that holds none of the source''s text satisfies the VERIFIED-needs-a-retrieval refusal. REF-00990 and REF-00991 each logged an 800-byte e-Gov app shell (sha256 prefix d984761f) as a retrieval. The refusal proves a retrieval was logged, not that it holds the source''s text; the author diff covers content only for a JSON byline. A byte floor would be an arbitrary exception: decide the test.', '2026-11-20 06:55', 'session_2026-11-20-core-work', '2026-11-20 06:55', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-375', 'SW', 'P3', 'OPEN', 'run-pipeline', NULL, 'REF-01017 stores its original title with the diacritics stripped (esteettomyydesta; the source reads esteettomyydesta with the diacritics) and an English gloss inside the same cell, then was translated without being flagged. Correct the stored title through correct-source from the logged payload. || CORRECTED 2026-11-20: The stored title reads ''esteettomyydesta'' (ASCII o and a) where the source reads ''esteettömyydestä'' (o and a with diacritics); the description above wrote the source form without them by mistake.', '2026-11-20 06:55', 'session_2026-11-20-core-work', '2026-11-20 06:55', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability", "parameter_id", "identity_code", "icf_code", "needs_code", "jurisdiction", "language", "resolved_at", "resolved_by_session", "resolution_ref", "resolution_kind") VALUES ('GAP-376', 'SW', 'P3', 'OPEN', 'run-pipeline', NULL, 'Duplicate sources hold the same document and each was translated twice: REF-01026 and REF-01032 (the same Decree-Law 163/2006; figures 95-97 equal 109-111) and REF-01019 and REF-01031 (the same Korean annex; figures 82-83 equal 107-108). Decide whether each pair is one source with two ref_ids to merge, or two retrievals to keep.', '2026-11-20 06:55', 'session_2026-11-20-core-work', '2026-11-20 06:55', 'session_2026-11-20-core-work', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);